// Arbeitsliste als HTML-Seite: Überblick, Filter, offene Aufgaben nach Team, Review-Queue. Werte werden escaped, weil Mailtexte von außen kommen.
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const reviews = $('Offene Reviews laden').all().map((i) => i.json).filter((r) => r.id);
const tickets = $('Tickets laden').all().map((i) => i.json).filter((r) => r.id);

// Symbole (Linien-Stil, 24er-Raster)
const PFAD = {
  mail: '<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/>',
  check: '<path d="m5 12.5 4.5 4.5L19 7.5"/>',
  alarm: '<path d="M12 4 3 19h18L12 4Z"/><path d="M12 10v4M12 17v.5"/>',
  inbox: '<path d="M4 13V6a2 2 0 0 1 2-2h12a2 2 0 0 1 2 2v7"/><path d="M4 13h4l1 2h6l1-2h4v5a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2v-5Z"/>',
  robot: '<rect x="4" y="8" width="16" height="11" rx="3"/><path d="M12 4v4M9 13v1M15 13v1"/>',
  suche: '<circle cx="11" cy="11" r="6"/><path d="m20 20-4.2-4.2"/>',
  pfeil: '<path d="m9 6 6 6-6 6"/>',
  senden: '<path d="M4 12 20 4l-4 16-4-6-8-2Z"/>',
  neu: '<path d="M20 12a8 8 0 1 1-2.3-5.7M20 4v5h-5"/>',
};
const icon = (name, klasse = 'ico') => `<svg class="${klasse}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${PFAD[name]}</svg>`;

const KATEGORIE = {
  angebot: 'Angebot', auftragsbestaetigung: 'Auftragsbestätigung', reklamation: 'Reklamation', lieferverzug: 'Lieferverzug',
  rechnung: 'Rechnung', lieferavis: 'Lieferavis', preisaenderung: 'Preisänderung', stammdatenaenderung: 'Stammdaten',
  compliance: 'Compliance', werbung: 'Werbung', sonstiges: 'Sonstiges',
};

// Abweichungen und Prüfgründe der AB-Prüfung in Sätze übersetzen, die ein Einkäufer sofort versteht
const beschreibe = (ab) => {
  const zahl = (n) => Number(n).toLocaleString('de-DE', { maximumFractionDigits: 4 });
  const datum = (d) => (d ? (typeof d === 'string' ? d : new Date(d).toISOString()).slice(0, 10).split('-').reverse().join('.') : '–');
  const texte = (ab.abweichungen ?? []).map((a) => ({
    preis: `Preis ${zahl(a.bestellt)} → ${zahl(a.bestaetigt)} ${a.waehrung ?? ''}`,
    waehrung: `Währung ${a.bestellt} → ${a.bestaetigt}: Preis in anderer Währung bestätigt`,
    menge: `Menge ${zahl(a.bestellt)} → ${zahl(a.bestaetigt)}${a.grund ? ` (${a.grund})` : ''}`,
    stammdaten_pruefen: `Stammdaten prüfen${a.hinweis ? `: ${a.hinweis}` : ''}`,
    termin_unsicher: `Termin unsicher, gewünscht ${datum(a.gewuenscht)}`,
    termin_fehlt: `Kein Termin bestätigt, gewünscht ${datum(a.gewuenscht)}`,
    termin_spaeter: `Termin ${datum(a.gewuenscht)} → ${datum(a.bestaetigt)}`,
  }[a.art] ?? a.art));
  for (const g of ab.pruefgruende ?? []) {
    texte.push({
      neuer_lieferant: 'Neuer Lieferant: Kontakt aufnehmen und Termin absichern',
      liefertreue_unter_schwelle: `Liefertreue ${ab.liefertreue} % unter ${ab.schwelle} % (${ab.abc_xyz}-Artikel)`,
      blindbestaetigung_verdacht: `AB nach ${ab.bearbeitungszeit_minuten} Minuten: Blindbestätigung?`,
      absender_domain_abweichend: 'Absender-Domain passt nicht zum Lieferanten',
    }[g] ?? g);
  }
  return texte;
};

const FELD = { einzelpreis: 'Einzelpreis', menge: 'Menge', betrag: 'Betrag', liefertermin: 'Liefertermin', bestellnummer: 'Bestellnummer', rechnungsnummer: 'Rechnungsnummer', angebotsnummer: 'Angebotsnummer' };
const warnung = (w) => {
  const [art, wert] = String(w).split(':');
  if (art === 'beleg_fehlt') return `${FELD[wert] ?? wert} nicht im Mailtext belegt`;
  return String(w);
};
const GRUND = {
  konfidenz_niedrig: 'Modell war unsicher', bankdatenaenderung: 'Bankdaten geändert: Betrugsverdacht', stammdatenaenderung_pruefen: 'Stammdatenänderung: immer prüfen',
  prompt_injection_verdacht: 'Verdacht auf Manipulation des Modells', bestellung_unbekannt: 'Bestellnummer nicht im System', kategorie_unplausibel: 'Kategorie unplausibel',
  llm_fehler: 'Modell nicht erreichbar', json_ungueltig: 'Antwort des Modells ungültig', schema_verletzt: 'Antwort des Modells ungültig',
};
const grund = (g) => (String(g).startsWith('pflichtfeld_fehlt:') ? `Pflichtangabe fehlt: ${String(g).split(':')[1].replace('|', ' oder ')}` : GRUND[g] ?? String(g));

const adresse = (absender) => String(absender ?? '').match(/<([^>]+)>/)?.[1] ?? String(absender ?? '').trim();
const anbieter = (t) => t.lieferant || String(t.absender ?? '').replace(/<[^>]*>/g, '').trim() || 'Unbekannter Absender';
const mailto = (an, betreff, text) => `mailto:${esc(encodeURIComponent(an ?? '').replace(/%40/g, '@'))}?subject=${esc(encodeURIComponent(betreff ?? ''))}&amp;body=${esc(encodeURIComponent(text ?? ''))}`;
const chip = (text, art = '') => `<span class="chip ${art}">${esc(text)}</span>`;

// Anfrage (RFQ) im Format, das der Procurement-RAG-Agent auslesen kann: eine Angabe je Zeile, mit Einheit
const rfq = (t) => {
  const gegenstand = t.artikel || (t.kategorie === 'angebot' ? t.betreff : '[Artikel eintragen]');
  const einleitung = t.kategorie === 'preisaenderung'
    ? `vielen Dank für Ihre Information zur Preisänderung. Bevor wir entscheiden, möchten wir ein aktuelles, vollständiges Angebot einholen für: ${gegenstand}.`
    : `vielen Dank für Ihr Angebot. Damit wir es mit anderen vergleichen können, bitten wir um ein vollständiges Angebot zu: ${gegenstand}.`;
  return {
    betreff: `Anfrage (RFQ): ${gegenstand}`,
    text: [
      'Guten Tag,', '', einleitung, '',
      'Bitte beantworten Sie jeden Punkt einzeln und mit Einheit, damit wir Angebote vergleichen können:',
      '1. Stückpreis in EUR, netto, je 1 Stück',
      '2. Mindestbestellmenge in Stück',
      '3. Lieferzeit in Tagen nach Auftragseingang',
      '4. Zahlungsziel in Tagen',
      '5. Skonto in Prozent (0, wenn keines)',
      '6. Preisgleitklausel: ja oder nein (Preis an einen Index gekoppelt?)',
      '7. Zertifizierung ISO 9001: gültig ja oder nein, mit Gültigkeitsdatum',
      '8. Zertifizierung ISO 14001: gültig ja oder nein, mit Gültigkeitsdatum',
      '9. CO2-Fußabdruck je Stück in kg CO2e',
      '10. Reklamationsquote in Prozent (letzte 12 Monate)',
      '11. Liefertreue in Prozent (letzte 12 Monate)',
      '',
      'Bitte senden Sie das Angebot als PDF mit Angebotsnummer und Gültigkeitsdatum sowie die ausgefüllte Lieferantenselbstauskunft.',
      'Angebotsfrist: [Datum eintragen]', '',
      'Mit freundlichen Grüßen', '[Name]', 'Hagemann Antriebstechnik GmbH, Einkauf',
    ].join('\n'),
  };
};

const karte = (t) => {
  const ab = t.ab_pruefung ?? {};
  const hinweise = [
    ...(t.kategorie === 'auftragsbestaetigung' ? beschreibe(ab).map((x) => chip(x, 'warn')) : []),
    ...(t.warnungen ?? []).filter((w) => !String(w).startsWith('kategorie_korrigiert')).map((w) => chip(warnung(w), 'info')),
  ].join('');
  const entwurf = t.entwurf_text
    ? `<details class="panel"><summary>${icon('mail')}Antwortentwurf (${esc(t.foermlichkeit)}, ${esc(t.nachdruck)})</summary>
        ${(t.entwurf_warnungen ?? []).length ? `<p class="hinweis">Bitte prüfen: ${t.entwurf_warnungen.map(esc).join(', ')}</p>` : ''}
        <pre><b>${esc(t.entwurf_betreff)}</b>\n\n${esc(t.entwurf_text)}</pre>
        <a class="knopf" href="${mailto(t.entwurf_empfaenger, t.entwurf_betreff, t.entwurf_text)}">${icon('senden')}In Mailprogramm öffnen</a></details>`
    : '';
  const anfrage = ['angebot', 'preisaenderung'].includes(t.kategorie) ? rfq(t) : null;
  const anfrageBlock = anfrage
    ? `<details class="panel"><summary>${icon('mail')}Angebot anfordern (RFQ-Entwurf)</summary>
        <pre><b>${esc(anfrage.betreff)}</b>\n\n${esc(anfrage.text)}</pre>
        <a class="knopf" href="${mailto(adresse(t.absender), anfrage.betreff, anfrage.text)}">${icon('senden')}In Mailprogramm öffnen</a></details>`
    : '';
  const meta = [t.bestellnummer ? `Bestellung ${t.bestellnummer}` : '', t.artikel, t.angebotsnummer ? `Angebot ${t.angebotsnummer}` : '',
    t.rechnungsnummer ? `Rechnung ${t.rechnungsnummer}` : '', t.betrag ? `${Number(t.betrag).toLocaleString('de-DE', { minimumFractionDigits: 2 })} ${t.waehrung ?? ''}` : '',
    t.zustaendig ? `zuständig: ${t.zustaendig}` : ''].filter(Boolean).map(esc).join(' · ');
  const noch = t.kategorie === 'auftragsbestaetigung' && !t.entwurf_text && beschreibe(ab).length
    ? `<a class="knopf" href="/form/entwurf">${icon('mail')}Antwortentwurf erstellen</a>` : '';
  const erledigt = `<form method="post" action="/webhook/aufgabe"><input type="hidden" name="id" value="${esc(t.id)}"><input type="hidden" name="token" value="${esc(t.token)}"><button class="knopf haupt" type="submit">${icon('check')}Erledigt</button></form>`;
  return `<article class="aufgabe dringlich-${esc(t.dringlichkeit ?? 'niedrig')}" data-team="${esc(t.team)}" data-text="${esc(`${anbieter(t)} ${t.betreff} ${t.zusammenfassung ?? ''} ${t.bestellnummer ?? ''} ${t.artikel ?? ''}`.toLowerCase())}">
    <div class="kopfzeile"><span class="kat kat-${esc(t.kategorie)}">${esc(KATEGORIE[t.kategorie] ?? t.kategorie)}</span>${t.dringlichkeit === 'hoch' ? '<span class="dringend">Dringend</span>' : ''}<span class="zeit">${esc(t.erstellt)}</span></div>
    <h3>${esc(anbieter(t))} <span class="betreff">${esc(t.betreff)}</span></h3>
    ${t.zusammenfassung ? `<p class="zusammenfassung">${esc(t.zusammenfassung)}</p>` : ''}
    <p class="meta">${meta}</p>
    ${hinweise ? `<div class="chips">${hinweise}</div>` : ''}
    ${entwurf}${anfrageBlock}
    <div class="aktionen">${erledigt}${noch}</div>
  </article>`;
};

const offen = tickets.filter((t) => t.status === 'offen');
const automatisch = tickets.filter((t) => ['bestaetigt', 'abgelegt'].includes(t.status));
const REIHENFOLGE = ['Einkauf', 'Strategischer Einkauf', 'Disposition', 'Qualitätsmanagement', 'Kreditorenbuchhaltung', 'Einkauf Sammelpostfach'];
const rang = (team) => (REIHENFOLGE.indexOf(team) === -1 ? 99 : REIHENFOLGE.indexOf(team));
const teams = [...new Set(offen.map((t) => t.team))].sort((a, b) => rang(a) - rang(b));

const teamBloecke = teams.map((team) => {
  const liste = offen.filter((t) => t.team === team);
  return `<section class="gruppe" data-gruppe="${esc(team)}"><h2>${esc(team)}<span class="zahl">${liste.length}</span></h2>${liste.map(karte).join('')}</section>`;
}).join('');

const reviewKarten = reviews.map((r) => `
  <article class="aufgabe pruefung" data-team="Prüfung" data-text="${esc(`${r.betreff} ${r.absender}`.toLowerCase())}">
    <div class="kopfzeile"><span class="kat kat-pruefung">Prüfung nötig</span><span class="zeit">${esc(r.erstellt)}</span></div>
    <h3>${esc(r.betreff)}</h3>
    <p class="meta">${esc(r.absender)}</p>
    <div class="chips">${r.gruende.map((g) => chip(grund(g), 'warn')).join('')}</div>
    <p class="zusammenfassung">Vorschlag des Modells: <b>${esc(KATEGORIE[r.vorschlag] ?? r.vorschlag ?? '–')}</b> (Konfidenz ${esc(r.konfidenz ?? '–')}). ${esc(r.begruendung ?? '')}</p>
    <details class="panel"><summary>${icon('mail')}Mailtext anzeigen</summary><pre>${esc(r.text)}</pre></details>
    <div class="aktionen"><a class="knopf haupt" href="/form/review">${icon('check')}Review abschließen (ID ${esc(r.id)})</a></div>
  </article>`).join('');

const automatischZeilen = automatisch.slice(0, 30).map((t) =>
  `<li><span class="kat kat-${esc(t.kategorie)} klein">${esc(KATEGORIE[t.kategorie] ?? t.kategorie)}</span><span class="text"><b>${esc(anbieter(t))}</b> ${esc(t.betreff)}</span><span class="zeit">${esc(t.status === 'abgelegt' ? 'abgelegt' : 'bestätigt')} · ${esc(t.erstellt)}</span></li>`).join('');

const filter = [`<button class="filter aktiv" type="button" data-filter="">Alle<span>${offen.length + reviews.length}</span></button>`]
  .concat(reviews.length ? [`<button class="filter" type="button" data-filter="Prüfung">Prüfung<span>${reviews.length}</span></button>`] : [])
  .concat(teams.map((team) => `<button class="filter" type="button" data-filter="${esc(team)}">${esc(team)}<span>${offen.filter((t) => t.team === team).length}</span></button>`)).join('');

const uhr = new Date().toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' });
const leer = !offen.length && !reviews.length;

const html = `<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Arbeitsliste Einkauf</title>
<style>
  :root {
    --bg: #f6f7f9; --flaeche: #ffffff; --linie: #e4e7ec; --linie-stark: #d0d5dd;
    --text: #101828; --text-2: #475467; --text-3: #667085;
    --akzent: #4f46e5; --akzent-dunkel: #4338ca; --akzent-hell: #eef2ff;
    --ok: #067647; --ok-hell: #ecfdf3; --warn: #b54708; --warn-hell: #fffaeb; --rot: #b42318; --rot-hell: #fef3f2;
    --radius: 12px; --schatten: 0 1px 2px rgba(16, 24, 40, .05); --schatten-hover: 0 4px 12px rgba(16, 24, 40, .08);
  }
  * { box-sizing: border-box; }
  body { margin: 0; background: var(--bg); color: var(--text); font: 14px/1.5 ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif; -webkit-font-smoothing: antialiased; }
  .ico { width: 16px; height: 16px; flex: none; }
  .leiste { position: sticky; top: 0; z-index: 10; background: rgba(255, 255, 255, .9); backdrop-filter: blur(8px); border-bottom: 1px solid var(--linie); }
  .leiste-innen { max-width: 1040px; margin: 0 auto; padding: 12px 20px; display: flex; align-items: center; gap: 12px; }
  .logo { width: 32px; height: 32px; border-radius: 9px; background: linear-gradient(135deg, #6366f1, #4338ca); color: #fff; display: grid; place-items: center; }
  .logo .ico { width: 18px; height: 18px; }
  .leiste h1 { font-size: 15px; margin: 0; font-weight: 650; letter-spacing: -.01em; } .leiste .unter { color: var(--text-3); font-size: 12px; }
  .rechts { margin-left: auto; display: flex; align-items: center; gap: 12px; color: var(--text-3); font-size: 12px; }
  .rechts a { color: var(--text-2); text-decoration: none; display: inline-flex; align-items: center; gap: 6px; padding: 6px 10px; border: 1px solid var(--linie); border-radius: 8px; background: #fff; }
  .rechts a:hover { background: var(--bg); }
  main { max-width: 1040px; margin: 0 auto; padding: 24px 20px 56px; }
  .kennzahlen { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; margin-bottom: 22px; }
  .kennzahl { background: var(--flaeche); border: 1px solid var(--linie); border-radius: var(--radius); padding: 16px 18px; box-shadow: var(--schatten); display: flex; gap: 14px; align-items: center; }
  .kennzahl .symbol { width: 40px; height: 40px; border-radius: 10px; display: grid; place-items: center; background: var(--akzent-hell); color: var(--akzent); }
  .kennzahl .symbol .ico { width: 20px; height: 20px; } .kennzahl.gelb .symbol { background: var(--warn-hell); color: var(--warn); } .kennzahl.gruen .symbol { background: var(--ok-hell); color: var(--ok); }
  .kennzahl b { display: block; font-size: 26px; line-height: 1.1; letter-spacing: -.02em; font-variant-numeric: tabular-nums; } .kennzahl span.t { color: var(--text-3); font-size: 12.5px; }
  .werkzeuge { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; margin-bottom: 8px; }
  .suche { position: relative; flex: 1 1 260px; max-width: 360px; } .suche .ico { position: absolute; left: 11px; top: 10px; color: var(--text-3); }
  .suche input { width: 100%; height: 36px; padding: 0 12px 0 34px; border: 1px solid var(--linie-stark); border-radius: 9px; font: inherit; background: #fff; color: var(--text); }
  .suche input:focus, .knopf:focus-visible, .filter:focus-visible, summary:focus-visible { outline: 2px solid var(--akzent); outline-offset: 2px; }
  .filterleiste { display: flex; flex-wrap: wrap; gap: 8px; }
  .filter { height: 32px; padding: 0 12px; border: 1px solid var(--linie); border-radius: 999px; background: #fff; color: var(--text-2); font: inherit; font-size: 13px; cursor: pointer; display: inline-flex; align-items: center; gap: 8px; }
  .filter span { font-size: 11.5px; color: var(--text-3); background: var(--bg); border-radius: 999px; padding: 0 7px; font-variant-numeric: tabular-nums; }
  .filter:hover { border-color: var(--linie-stark); } .filter.aktiv { background: var(--text); border-color: var(--text); color: #fff; } .filter.aktiv span { background: rgba(255,255,255,.18); color: #fff; }
  h2 { font-size: 12.5px; text-transform: uppercase; letter-spacing: .06em; color: var(--text-3); font-weight: 600; margin: 26px 0 10px; display: flex; align-items: center; gap: 8px; }
  h2 .zahl { background: var(--flaeche); border: 1px solid var(--linie); border-radius: 999px; padding: 0 8px; font-size: 11.5px; letter-spacing: 0; text-transform: none; font-variant-numeric: tabular-nums; }
  .aufgabe { background: var(--flaeche); border: 1px solid var(--linie); border-radius: var(--radius); padding: 16px 18px 14px; margin-bottom: 10px; box-shadow: var(--schatten); position: relative; transition: box-shadow .15s, border-color .15s; }
  .aufgabe:hover { box-shadow: var(--schatten-hover); border-color: var(--linie-stark); }
  .aufgabe.dringlich-hoch { box-shadow: inset 3px 0 0 #f04438, var(--schatten); } .aufgabe.pruefung { box-shadow: inset 3px 0 0 #f79009, var(--schatten); background: #fffcf5; border-color: #fedf89; }
  .kopfzeile { display: flex; align-items: center; gap: 8px; margin-bottom: 6px; } .zeit { margin-left: auto; color: var(--text-3); font-size: 12px; white-space: nowrap; }
  .kat { display: inline-block; font-size: 11.5px; font-weight: 600; padding: 2px 9px; border-radius: 999px; background: #f2f4f7; color: #344054; white-space: nowrap; } .kat.klein { font-size: 11px; padding: 1px 8px; }
  .kat-auftragsbestaetigung, .kat-lieferavis { background: #eff8ff; color: #175cd3; } .kat-angebot, .kat-preisaenderung { background: #f4f3ff; color: #5925dc; }
  .kat-reklamation, .kat-lieferverzug { background: #fff6ed; color: #c4320a; } .kat-rechnung { background: #ecfdf3; color: #067647; }
  .kat-stammdatenaenderung, .kat-compliance, .kat-pruefung { background: #fffaeb; color: #b54708; } .kat-werbung, .kat-sonstiges { background: #f2f4f7; color: #475467; }
  .dringend { font-size: 11.5px; font-weight: 600; color: var(--rot); background: var(--rot-hell); padding: 2px 9px; border-radius: 999px; }
  h3 { margin: 0; font-size: 15px; font-weight: 650; letter-spacing: -.01em; line-height: 1.35; } h3 .betreff { font-weight: 450; color: var(--text-2); }
  .zusammenfassung { margin: 6px 0 2px; color: var(--text); } .meta { margin: 4px 0 0; color: var(--text-3); font-size: 12.5px; }
  .chips { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }
  .chip { font-size: 12.5px; padding: 2px 9px; border-radius: 7px; background: var(--bg); color: var(--text-2); border: 1px solid var(--linie); }
  .chip.warn { background: var(--warn-hell); color: var(--warn); border-color: #fedf89; }
  .panel { margin-top: 10px; border: 1px solid var(--linie); border-radius: 10px; background: #fcfcfd; } .panel summary { cursor: pointer; padding: 9px 12px; color: var(--akzent-dunkel); font-weight: 550; display: flex; align-items: center; gap: 8px; list-style: none; }
  .panel summary::-webkit-details-marker { display: none; } .panel[open] summary { border-bottom: 1px solid var(--linie); }
  .panel pre { white-space: pre-wrap; margin: 0; padding: 12px 14px; font: 13px/1.55 ui-monospace, 'SF Mono', Consolas, monospace; color: var(--text); }
  .panel .knopf { margin: 0 12px 12px; } .hinweis { margin: 8px 12px 0; color: var(--warn); font-size: 12.5px; }
  .aktionen { display: flex; gap: 8px; flex-wrap: wrap; margin-top: 14px; } .aktionen form { margin: 0; }
  .knopf { height: 34px; padding: 0 14px; border: 1px solid var(--linie-stark); border-radius: 9px; background: #fff; color: var(--text); font: inherit; font-size: 13px; font-weight: 550; cursor: pointer; display: inline-flex; align-items: center; gap: 7px; text-decoration: none; box-shadow: var(--schatten); }
